<?php
namespace App\Http\Controllers\Admin;
use App\Models\Category;use App\Models\Product;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\View\View;use Illuminate\Http\RedirectResponse;
class ProductController {
 public function index():View{return view('admin.products.index',['products'=>Product::with('category')->latest()->paginate(20)]);}public function create():View{return view('admin.products.form',['product'=>new Product(),'categories'=>Category::orderBy('name')->get()]);}public function store(Request $r):RedirectResponse{$d=$this->data($r);$d['slug']=Str::slug($d['name']).'-'.Str::lower(Str::random(5));Product::create($d);return redirect()->route('admin.products.index')->with('status','Product added.');}public function edit(Product $product):View{return view('admin.products.form',['product'=>$product,'categories'=>Category::orderBy('name')->get()]);}public function update(Request $r,Product $product):RedirectResponse{$product->update($this->data($r));return redirect()->route('admin.products.index')->with('status','Product updated.');}public function destroy(Product $product):RedirectResponse{$product->delete();return back()->with('status','Product removed.');}
 private function data(Request $r):array{$d=$r->validate(['category_id'=>'nullable|exists:categories,id','name'=>'required|string|max:180','description'=>'nullable|string|max:10000','price'=>'required|numeric|min:0.01','stock'=>'required|integer|min:0','image_url'=>'nullable|url|max:2048','is_active'=>'nullable|boolean']);$d['price_cents']=(int)round($d['price']*100);unset($d['price']);$d['is_active']=$r->boolean('is_active');return $d;}}
